using System;using System.Linq;using System.Threading.Tasks;using System.Windows.Forms;using Microsoft.EntityFrameworkCore;using PharmaCore.Infrastructure.Data;
using PharmaCore.Domain.Entities;using PharmaCore.Infrastructure.Entities;
namespace PharmaCore.ActivationManager
{
    public partial class FrmBranchUsers : Form
    {
        private string _cs => Home.ActiveConnectionString
            ?? throw new InvalidOperationException("No server selected.");
        public FrmBranchUsers(){ InitializeComponent(); }
        private async void FrmBranchUsers_Load(object sender, EventArgs e){ if(cboBranch==null){ MessageBox.Show("Branch combo missing from designer."); return; } try { await LoadOrgsAsync(); Wire(); await RefreshAsync(); } catch(Exception ex) { MessageBox.Show($"خطأ في الاتصال بقاعدة البيانات:\n{ex.Message}\n\nتأكد أن السيرفر شغال وبورت 5432 مفتوح.", "خطأ اتصال", MessageBoxButtons.OK, MessageBoxIcon.Error); } }
        private void Wire(){ if(cboBranch==null) return; btnAdd.Click += async (_,__) => await AddAsync(); btnRefresh.Click += async (_,__) => await RefreshAsync(); btnUpdate.Click += async (_,__) => await UpdateAsync(); grid.CellContentClick += Grid_CellContentClick; cboOrg.SelectedIndexChanged += async (_,__) => { ClearAfter(cboOrg); try { await LoadTenantsAsync(); await LoadRolesAsync(); await RefreshAsync(); } catch(Exception ex){ MessageBox.Show(ex.Message, "خطأ"); } }; cboTenant.SelectedIndexChanged += async (_,__) => { ClearAfter(cboTenant); try { await LoadRegionsAsync(); await RefreshAsync(); } catch(Exception ex){ MessageBox.Show(ex.Message, "خطأ"); } }; cboRegion.SelectedIndexChanged += async (_,__) => { ClearAfter(cboRegion); try { await LoadBranchesAsync(); await RefreshAsync(); } catch(Exception ex){ MessageBox.Show(ex.Message, "خطأ"); } }; cboBranch.SelectedIndexChanged += async (_,__) => { try { await RefreshAsync(); } catch(Exception ex){ MessageBox.Show(ex.Message, "خطأ"); } }; }
        private void ClearAfter(Control c){ if(c==cboOrg){ cboTenant.DataSource=null; cboRegion.DataSource=null; cboBranch.DataSource=null; } else if(c==cboTenant){ cboRegion.DataSource=null; cboBranch.DataSource=null; } else if(c==cboRegion){ cboBranch.DataSource=null; } }
        private AppDbContext CreateDb(Guid orgId)=> new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseNpgsql(_cs).Options, new PharmaCore.LicenseGenerator.SimpleTenantContext(orgId));
        private async Task LoadOrgsAsync(){ using var db = new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseNpgsql(_cs).Options, new PharmaCore.LicenseGenerator.SimpleTenantContext(Guid.Empty)); var orgs = await db.Organizations.IgnoreQueryFilters().AsNoTracking().OrderBy(o=>o.Name).ToListAsync(); cboOrg.DataSource=orgs; cboOrg.DisplayMember="Name"; cboOrg.ValueMember="Id"; cboOrg.SelectedIndex=-1; cboTenant.DataSource=null; cboRegion.DataSource=null; cboBranch.DataSource=null; cboTenant.Enabled=false; cboRegion.Enabled=false; cboBranch.Enabled=false; if(orgs.Count==1){ cboOrg.SelectedValue = orgs[0].Id; } }
        private async Task LoadTenantsAsync(){ cboTenant.DataSource=null; cboRegion.DataSource=null; cboBranch.DataSource=null; cboRegion.Enabled=false; cboBranch.Enabled=false; if(cboOrg.SelectedValue is not Guid orgId){ cboTenant.Enabled=false; return; } using var db = new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseNpgsql(_cs).Options, new PharmaCore.LicenseGenerator.SimpleTenantContext(orgId)); var items = await db.Tenants.AsNoTracking().OrderBy(x=>x.Name).ToListAsync(); cboTenant.DataSource=items; cboTenant.DisplayMember="Name"; cboTenant.ValueMember="Id"; cboTenant.SelectedIndex=-1; cboTenant.Enabled=true; if(items.Count==1){ cboTenant.SelectedValue = items[0].Id; } }
        private async Task LoadRegionsAsync(){ cboRegion.DataSource=null; cboBranch.DataSource=null; cboBranch.Enabled=false; if(cboOrg.SelectedValue is not Guid orgId || cboTenant.SelectedValue is not Guid tenId){ cboRegion.Enabled=false; return;} using var db = new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseNpgsql(_cs).Options, new PharmaCore.LicenseGenerator.SimpleTenantContext(orgId)); var items = await db.Regions.AsNoTracking().Where(r=>r.TenantId==tenId).OrderBy(x=>x.Name).ToListAsync(); cboRegion.DataSource=items; cboRegion.DisplayMember="Name"; cboRegion.ValueMember="Id"; cboRegion.SelectedIndex=-1; cboRegion.Enabled=true; if(items.Count==1){ cboRegion.SelectedValue = items[0].Id; } }
        private async Task LoadBranchesAsync(){ cboBranch.DataSource=null; if(cboOrg.SelectedValue is not Guid orgId || cboRegion.SelectedValue is not Guid regId){ cboBranch.Enabled=false; return;} using var db = new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseNpgsql(_cs).Options, new PharmaCore.LicenseGenerator.SimpleTenantContext(orgId)); var items = await db.Branches.AsNoTracking().Where(b=>b.RegionId==regId).OrderBy(x=>x.Name).ToListAsync(); cboBranch.DataSource=items; cboBranch.DisplayMember="Name"; cboBranch.ValueMember="Id"; cboBranch.SelectedIndex=-1; cboBranch.Enabled=true; if(items.Count==1){ cboBranch.SelectedValue = items[0].Id; } }
        private async Task RefreshAsync(){ try { Guid orgId = cboOrg.SelectedValue is Guid og? og: Guid.Empty; Guid tenantId = cboTenant.SelectedValue is Guid tg? tg: Guid.Empty; Guid regionId = cboRegion.SelectedValue is Guid rg? rg: Guid.Empty; Guid branchId = cboBranch.SelectedValue is Guid br? br: Guid.Empty; await BranchUserAdmin.EnsureSchemaAsync(_cs); var list = await BranchUserAdmin.ListViewAsync(_cs, orgId, tenantId, regionId, branchId); grid.DataSource = list.ToList(); EnsureGridColumns(); if(grid.Columns.Contains("PasswordPlain")) grid.Columns["PasswordPlain"].Visible=false; } catch(Exception ex) { MessageBox.Show($"خطأ في الاتصال بقاعدة البيانات:\n{ex.Message}", "خطأ اتصال", MessageBoxButtons.OK, MessageBoxIcon.Error); } }
        private void EnsureGridColumns(){ if(grid.Columns["ResetHWID"]==null){ var col = new DataGridViewButtonColumn{ Name="ResetHWID", HeaderText="Reset HWID", Text="Reset", UseColumnTextForButtonValue=true, Width=70}; grid.Columns.Insert(0,col);} if(grid.Columns["CopyPass"]==null){ var col = new DataGridViewButtonColumn{ Name="CopyPass", HeaderText="Copy Pass", Text="CopyP", UseColumnTextForButtonValue=true, Width=70}; grid.Columns.Insert(0,col);} if(grid.Columns["CopyUser"]==null){ var col = new DataGridViewButtonColumn{ Name="CopyUser", HeaderText="Copy User", Text="CopyU", UseColumnTextForButtonValue=true, Width=70}; grid.Columns.Insert(0,col);} if(grid.Columns["LoadEdit"]==null){ var col = new DataGridViewButtonColumn{ Name="LoadEdit", HeaderText="Load", Text="Load", UseColumnTextForButtonValue=true, Width=60}; grid.Columns.Insert(0,col);} }
        private async Task LoadRolesAsync(){ cboRole.DataSource=null; cboRole.Items.Clear(); if(cboOrg.SelectedValue is not Guid orgId) return; try { var roles = await BranchUserAdmin.ListRolesAsync(_cs, orgId); cboRole.DataSource = roles; if(roles.Count>0) cboRole.SelectedIndex=0; } catch { cboRole.Items.AddRange(new[]{ "Owner","Branch Manager","Pharmacist","Cashier","Staff" }); cboRole.SelectedIndex=0; } }
        private async Task AddAsync(){ if(cboOrg.SelectedValue is not Guid orgId || cboBranch.SelectedValue is not Guid branchId){ MessageBox.Show("Select Org->Tenant->Region->Branch"); return;} var user=txtUser.Text.Trim(); var pass=txtPass.Text; if(string.IsNullOrWhiteSpace(user) || string.IsNullOrWhiteSpace(pass)){ MessageBox.Show("Enter user & pass"); return;} if(!PasswordMeetsPolicy(pass)){ MessageBox.Show("كلمة المرور يجب ألا تقل عن 4 أحرف/أرقام."); return;} var role = cboRole.SelectedItem?.ToString(); if(string.IsNullOrWhiteSpace(role)){ MessageBox.Show("يرجى اختيار الرتبة"); return; } try{ await BranchUserAdmin.AddAsync(_cs, orgId, branchId, user, pass,(int)numAllowed.Value, role); await RefreshAsync(); txtUser.Clear(); txtPass.Clear(); } catch(Exception ex){ MessageBox.Show(ex.Message); } }
        private async Task UpdateAsync(){ if(grid.SelectedRows.Count==0){ MessageBox.Show("Select row"); return;} var row = grid.SelectedRows[0]; if(row.Cells["Id"].Value is not Guid id){ return;} string? newUser = string.IsNullOrWhiteSpace(txtUser.Text)? null: txtUser.Text.Trim(); string? newPass = string.IsNullOrWhiteSpace(txtPass.Text)? null: txtPass.Text; if(newPass!=null && !PasswordMeetsPolicy(newPass)){ MessageBox.Show("كلمة المرور يجب ألا تقل عن 4 أحرف/أرقام."); return; } int? allowed = (int)numAllowed.Value; bool? active = chkActive.Checked; var role = cboRole.SelectedItem?.ToString(); try{ await BranchUserAdmin.UpdateAsync(_cs, id, newUser, newPass, allowed, active, role); await RefreshAsync(); } catch(Exception ex){ MessageBox.Show(ex.Message); } }
        private async Task ResetSelectedAsync(){ if(grid.SelectedRows.Count==0){ MessageBox.Show("Select row"); return;} var row = grid.SelectedRows[0]; if(row.Cells["Id"].Value is not Guid id){ return;} await BranchUserAdmin.ResetDevicesAsync(_cs,id); await RefreshAsync(); }
        private async void Grid_CellContentClick(object? sender, DataGridViewCellEventArgs e){ if(e.RowIndex<0) return; var name = grid.Columns[e.ColumnIndex].Name; var r = grid.Rows[e.RowIndex]; if(name=="CopyUser"){ Clipboard.SetText(Convert.ToString(r.Cells["UserName"].Value)??""); } else if(name=="CopyPass"){ if(r.Cells["Id"].Value is Guid id){ var plain = await BranchUserAdmin.GetPlainPasswordAsync(_cs,id); if(!string.IsNullOrEmpty(plain)){ Clipboard.SetText(plain); } else MessageBox.Show("لا توجد كلمة مرور مخزنة","تنبيه"); } } else if(name=="LoadEdit"){ txtUser.Text = Convert.ToString(r.Cells["UserName"].Value)??""; txtPass.Clear(); chkActive.Checked = r.Cells["IsActive"].Value is bool b && b; numAllowed.Value = Convert.ToDecimal(r.Cells["AllowedDevices"].Value??1); var roleVal = Convert.ToString(r.Cells["Role"].Value)??""; for(int i=0;i<cboRole.Items.Count;i++){ if(cboRole.Items[i]?.ToString()==roleVal){ cboRole.SelectedIndex=i; break; } } grid.Rows[e.RowIndex].Selected=true; } else if(name=="ResetHWID"){ if(MessageBox.Show("إعادة تعيين الأجهزة لهذا المستخدم؟","Reset",MessageBoxButtons.YesNo,MessageBoxIcon.Question)==DialogResult.Yes){ if(r.Cells["Id"].Value is Guid id){ await BranchUserAdmin.ResetDevicesAsync(_cs,id); await RefreshAsync(); } } } }
        private bool PasswordMeetsPolicy(string p){ return p?.Length >= 4; }
    }
}